struct Image { int w=0,h=0; std::vector<uint8_t> rgba; };
struct P3 { float x,y,z; };
static inline float clamp01(float x){return std::max(0.f,std::min(1.f,x));}
static inline float srgb_to_linear(float x){return x<=0.04045f?x/12.92f:std::pow((x+0.055f)/1.055f,2.4f);}
static inline float linear_to_srgb(float x){x=clamp01(x);return x<=0.0031308f?12.92f*x:1.055f*std::pow(x,1.f/2.4f)-0.055f;}
