float edge(const float* a,const float* b,float x,float y){return (x-a[0])*(b[1]-a[1])-(y-a[1])*(b[0]-a[0]);}
struct RayTri { P3 p[3]; P3 n[3]; std::array<float,2> uv[3]; };
struct Transfer { std::vector<uint8_t> color,mr; std::vector<uint8_t> covered; uint64_t hit=0, fallback_uv=0, miss=0, long_hit=0, chart_overlap=0, edge_duplicate=0, raster_texels=0, gutter_texels=0, labeled_texels=0; float max_ray=0; };
