void write_px(Image& im,int x,int y,const std::array<float,4>&c){size_t i=(size_t(y)*im.w+x)*4;for(int k=0;k<4;k++)im.rgba[i+k]=uint8_t(std::lround(clamp01(c[k])*255.f));}
