int main(int argc,char**argv){try{if(argc==2&&std::string(argv[1])=="--self-test"){Image im{2,2,{0,0,0,255,255,255,255,255,255,255,255,255,0,0,0,255}};auto s=sample(im,0.5f,0.5f,true),l=sample(im,0.5f,0.5f,false);if(std::abs(s[0]-0.73535698f)>0.01f||std::abs(l[0]-0.5f)>0.01f)throw std::runtime_error("sRGB/linear filtering self-test failed");std::cout<<"atlas-bake color self-test passed: sRGB linear-light midpoint and linear MR midpoint\n";return 0;}if(argc<3){std::cerr<<"Usage: glb_atlas_bake input.glb output.glb [report.txt] [target_triangles=4000] [resolution=1024] [normalized_error=0.02] [uv_weight=25]\n";return 2;}std::string report=argc>3?argv[3]:std::string(argv[2])+".bake.txt";uint32_t target=argc>4?uint32_t(std::stoul(argv[4])):4000;uint32_t res=argc>5?uint32_t(std::stoul(argv[5])):1024;float e=argc>6?std::stof(argv[6]):0.02f,w=argc>7?std::stof(argv[7]):25.f;if(res<64||res>8192)throw std::runtime_error("resolution must be 64..8192");run_bake(argv[1],argv[2],report,target,res,e,w);return 0;}catch(const std::exception&e){std::cerr<<"ERROR: "<<e.what()<<"\n";return 1;}}
